create table xxventuri.xxeba_product_class (
    id                 number not null enable,
    product_class_code varchar2(50 byte),
    product_class_name varchar2(100 byte),
    status             varchar2(1 byte),
    created_by         varchar2(255 byte),
    created_date       timestamp(6),
    updated_by         varchar2(255 byte),
    updated_date       timestamp(6),
    tax_percent        number
);

alter table xxventuri.xxeba_product_class
    add constraint xxeba_product_class_pk primary key ( id )
        using index enable;


